import json
for month, (title, body, srcs) in add.items():
    p = f'{month}.py'; s = open(p).read()
    if 'From the Discord' in s: continue
    i = s.index('\n  ],\n')
    s = s[:i] + f",\n    story('community', {json.dumps(title, ensure_ascii=False)},\n      {json.dumps(body, ensure_ascii=False)},\n      [{', '.join(srcs)}])" + s[i:]
    s = s.replace(",,\n    story('community', \"From", ",\n    story('community', \"From")
    open(p, 'w').write(s)
